import {coachMarkup} from './lab-coach.js?v=audit48';
import {screenPolicy,screenSession} from './lab-screen-policy.js?v=class47';
import * as E from './lab-engine.js?v=class47';
import {context,address,changeAddress,request,runCommand,subnet} from './lab-os-engine.js?v=class47';
import {lessons,projects,references} from './lab-learning-repos.js?v=class47';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
import {setupAdmin} from './lab-os-admin.js?v=class47';
import {setupOSPractice} from './lab-os-practice.js?v=class47';
import {configuration,adapter,configure} from './lab-os-config.js?v=class47';
import {displayPath} from './lab-os-files.js?v=class47';
import {commandCatalog} from './lab-os-command-catalog.js?v=class47';
import {appIcon} from './lab-os-icons.js?v=class47';
import {isBrowser,createBrowserState,visitBrowser,moveBrowser,browserMarkup} from './lab-browser.js?v=class47';
const apps={lab:'Lab console',repos:'Learning repositories',terminal:'Terminal',settings:'Settings',browser:'Google Chrome',firefox:'Mozilla Firefox',vms:'Virtual machines',cloud:'Cloud console',tools:'System tools'};
export function setupDesktop(api){
 const state=()=>api.getState();let machine=null,physical=null,owner=state(),app='repos',folder='home',lessonId=null,projectId=null,shell='powershell',log=[],history=[],historyIndex=0,notice='',maximized=false,minimized=false,guide=true,settingsTab='network',lastFocus=null,quizFeedback='',browserStates={browser:createBrowserState(),firefox:createBrowserState()},windowPosition=null,networkEditing=false,commandLibrary=false,commandFilter='',commandCategory='All',cwd='/';
 const dialog=document.createElement('section');dialog.id='osDesktop';dialog.setAttribute('aria-label','Operating system on the computer screen');dialog.hidden=true;dialog.open=false;document.body.append(dialog);const sessions=new Map();let availability='',controlView='home',controlTarget=null,controlSection=null,controlField=null,controlChoice=null;const chrome=document.createElement('div');chrome.id='osPracticeControls';chrome.hidden=true;document.body.append(chrome);const icon=k=>appIcon(k,ubuntu()?'ubuntu':'windows');
 const policy=()=>screenPolicy(state()),availableApps=()=>policy().apps.filter(k=>!ctx().vm||!['vms','cloud'].includes(k)),allowedLessons=()=>lessons.filter(l=>policy().lessons.includes(l.id)),allowedProjects=()=>projects.filter(p=>policy().projects.includes(p.id));
 const remember=()=>{if(machine)sessions.set(machine,{app,folder,lessonId,projectId,shell,log,history,browserStates,settingsTab,minimized,cwd});};
 const resetSession=()=>{app='repos';folder='home';lessonId=projectId=null;shell=ctx().os==='ubuntu'?'bash':'powershell';log=[];history=[];browserStates={browser:createBrowserState(),firefox:createBrowserState()};settingsTab='network';cwd='/';minimized=true;const old=sessions.get(machine);if(old)({app,folder,lessonId,projectId,shell,log,history,browserStates,settingsTab,minimized,cwd}=old);if(!availableApps().includes(app))app='repos';notice='';windowPosition=null;maximized=false;networkEditing=false;commandLibrary=false;admin.reset();};
 const $=id=>dialog.querySelector('#'+id)||chrome.querySelector('#'+id),ctx=()=>context(state(),machine),ubuntu=()=>ctx().os==='ubuntu';
 const admin=setupAdmin({context:ctx,state,id:()=>machine,draw,mark:e=>practice.mark(e),changed:r=>{if(r.ok)api.render?.();draw();},terminal:()=>openApp('terminal'),lesson:()=>{app='repos';lessonId='windows';folder='foundations';draw();},close:()=>{minimized=true;draw();}});
 const practice=setupOSPractice({context:ctx,state,address:()=>address(state(),machine),draw,changed:()=>{api.render?.();draw();},navigate:(kind,value)=>{if(kind==='tools'){admin.select(value);openApp('tools');}else if(kind==='settings'){settingsTab=value;openApp('settings');}else if(kind==='command'){openApp('terminal');$('osCommand').value=value;$('osCommand').focus();}else openApp(kind);},complete:k=>{progress().workflows??=[];if(!progress().workflows.includes(k))progress().workflows.push(k);}});
 const progress=()=>{state().desktopProgress??={opened:false,machines:{}};state().desktopProgress.machines??={};return state().desktopProgress.machines[machine]??={commands:[],quizzes:[],projects:[]};};
 const field=(id,label,value,type='text')=>`<label for="${id}">${label}<input id="${id}" type="${type}" value="${esc(value)}" autocomplete="off"></label>`;
 function open(id){if(owner!==state()){sessions.clear();practice.reset();machine=physical=null;owner=state();}const session=screenSession(state(),id,physical);if(!session.ok){api.result({ok:false,message:session.why});return false;}if(machine&&machine!==id)practice.endQuiet();remember();lastFocus=document.activeElement;physical=session.client;machine=session.target;owner=state();resetSession();state().desktopProgress??={opened:false,machines:{}};state().desktopProgress.opened=true;progress();dialog.dataset.physicalDevice=physical;dialog.dataset.sessionDevice=machine;dialog.open=true;dialog.hidden=false;draw();
 if(api.mountScreen&&!api.mountScreen(physical,dialog,close)){dialog.open=false;dialog.hidden=true;api.result({ok:false,message:'The 3D computer display is still loading. Try Laptop screen in a moment.'});return false;}placeChrome();dialog.querySelector('[data-osapp="repos"]')?.focus({preventScroll:true});api.render?.();return true;}
 function close(){api.parkControls?.();remember();dialog.open=false;dialog.hidden=true;chrome.hidden=true;document.body.append(chrome);api.unmountScreen?.();lastFocus?.focus?.({preventScroll:true});api.render?.();}
 function leaveRemote(){practice.endQuiet();remember();machine=physical;resetSession();app='vms';minimized=false;if(!availableApps().includes(app))app='repos';dialog.dataset.sessionDevice=machine;draw();}
 function openApp(name){if(name==='lab')controlView='home';if(!availableApps().includes(name)){notice='This tool is not enabled for '+policy().name+'.';draw();return;}app=name;if(name==='tools')practice.mark('tool:'+admin.tool);if(name==='settings')practice.mark('settings:'+settingsTab);minimized=false;notice='';quizFeedback='';draw();if(app==='terminal')$('osCommand')?.focus();}
 function chooseShell(k){shell=k;history=log.filter(r=>r.shell===shell).map(r=>r.command);historyIndex=history.length;}
 function shellName(){return shell==='bash'?'student@ubuntu:'+(cwd==='/'?'~':'~'+cwd)+'$':(shell==='cmd'?'':'PS ')+displayPath(cwd,shell)+'>';}
 function placeChrome(){const desk=document.getElementById('deviceScreenDesk');if(desk){desk.insertBefore(chrome,desk.querySelector('#worldStage'));chrome.inert=false;chrome.removeAttribute('aria-hidden');}chrome.hidden=!dialog.open;}
 function clockText(){const now=new Date();return {time:now.toLocaleTimeString([], {hour:'numeric',minute:'2-digit'}),date:now.toLocaleDateString(),ubuntu:now.toLocaleDateString([], {month:'short',day:'numeric'})+'  '+now.toLocaleTimeString([], {hour:'numeric',minute:'2-digit'})};}
 function appTitle(k){return k==='repos'?(ubuntu()?'Files':'File Explorer'):k==='terminal'?(ubuntu()?'student@ubuntu: ~':'Windows Terminal'):k==='tools'?admin.title():apps[k];}
 function coaching(){if(minimized)return 'Start here: open '+(ubuntu()?'Files in the left dock':'the yellow folder on the taskbar')+' → 01 · Foundations. Open Terminal to try commands.';if(isBrowser(app))return 'Enter https://example.com or click Example Domain. Reload checks this computer’s current network. Chrome and Firefox keep separate histories.';return {terminal:'Type help and press Enter. ↑ / ↓ recalls commands. Ctrl+L clears this shell. Outputs come from your lab connections.',settings:'Read the current address first. Select '+(ubuntu()?'IPv4 settings':'Edit')+' to change the address, then verify it in Terminal.',repos:'Open 01 · Foundations, follow a lesson, then try its command. Use 02 · Practice projects to check your work.',vms:'Create or start a guest on a prepared server, then open its Ubuntu desktop. The console stays on this laptop.',browser:'Enter https://example.com to test this computer’s modeled DNS, routing, and HTTPS path.'}[app]||'Only the tools for your current lab are enabled. Your changes affect this simulated build.';}
 function draw(){if(!machine)return;api.parkControls?.();availability=JSON.stringify(screenSession(state(),machine,physical));const c=ctx(),isUbuntu=c.os==='ubuntu',clock=clockText();dialog.className='os-desktop '+(isUbuntu?'os-ubuntu':'os-windows');
 chrome.innerHTML=`<div class="os-practice-row"><span><b>${esc(policy().name)}</b> · restricted OS simulation</span><div>${machine===physical?`<label>Practice OS <select id="osBootProfile" aria-label="Computer OS profile"><option value="Windows 11" ${isUbuntu?'':'selected'}>Windows 11</option><option value="Linux" ${isUbuntu?'selected':''}>Ubuntu 24.04 LTS</option></select></label>`:`<button id="osGuestBack">← Return to client</button>`}<button id="osGuideToggle" aria-pressed="${guide}">${guide?'✓ Coach on':'Coach off'}</button><button id="osSave">Save progress</button>${app==='terminal'&&!minimized?`<button id="osCommandHelp">${commandLibrary?'Close command library':'Command library'}</button>`:''}</div></div>${guide?`${(api.guideInfo?.()||api.challengeInfo?.())&&!practice.active?'<details class="os-extra-exercises"><summary>More OS exercises</summary>'+practice.render()+'</details>':practice.render()}${!practice.active&&!api.challengeInfo?.()?`<p class="os-outside-coach">${esc(coaching())}</p>`:''}`:''}`;
 dialog.innerHTML=`${machine!==physical?`<div class="os-remote-frame"><div class="os-remote-title">${icon('vms')}<b>${c.vm?'Virtual Machine Connection':'Server management console'} · ${esc(c.vm?.name||c.device?.name)}</b><span>Viewing through ${esc(E.find(state(),physical)?.name)}</span></div>`:''}<div class="os-workspace">${isUbuntu?`<div class="os-topline"><button id="osActivities" aria-label="Activities overview"><span class="os-workspace-pill"></span><span class="os-workspace-dot"></span></button><span class="os-gnome-clock">${clock.ubuntu}</span><button data-osapp="settings" aria-label="Open network settings">${icon('network')}${icon('volume')}⌄</button></div>`:''}<div class="os-wallpaper" aria-hidden="true"></div><nav class="os-desktop-icons" aria-label="Desktop shortcuts">${['lab','repos','browser','firefox'].filter(k=>availableApps().includes(k)).map(k=>`<button data-osapp="${k}" title="Open ${apps[k]}">${icon(k)}<span>${k==='lab'?'Lab console':k==='repos'?'Learning<br>Repositories':k==='browser'?'Google Chrome':'Firefox'}</span></button>`).join('')}</nav>${screenSession(state(),machine,physical).ok?`<section class="os-window ${maximized?'os-maximized':''} os-app-${app}" ${minimized?'hidden':''} style="${!maximized&&windowPosition?`--os-dx:${windowPosition.x}px;--os-dy:${windowPosition.y}px`:''}" aria-label="${apps[app]} window"><header class="os-titlebar"><div>${icon(app)}<b>${appTitle(app)}</b>${app==='terminal'&&!isUbuntu?'<span class="os-terminal-subtitle">'+(shell==='cmd'?'Command Prompt':'Windows PowerShell')+'</span>':''}</div><div class="os-window-controls"><button id="osMinimize" aria-label="Minimize window">─</button><button id="osMaximize" aria-label="${maximized?'Restore':'Maximize'} window">□</button><button id="osCloseApp" aria-label="Close application">×</button></div></header><div class="os-app-body">${renderApp()}</div></section>`:`<section class="os-power-off"><h2>Computer unavailable</h2><p>${esc(screenSession(state(),machine,physical).why)}</p><button id="osPowerReturn">Return to the lab and restore it</button></section>`}<nav class="os-taskbar" aria-label="${isUbuntu?'Ubuntu dock':'Windows taskbar'}"><button id="osStart" aria-label="${isUbuntu?'Show applications':'Start menu'}">${icon('start')}</button>${!isUbuntu?`<button id="osTaskSearch" aria-label="Search apps">${icon('search')}</button>`:''}${Object.entries(apps).filter(([k])=>availableApps().includes(k)).map(([k,t])=>`<button data-osapp="${k}" class="${app===k&&!minimized?'active':''}" aria-label="Open ${t}" title="${appTitle(k)}">${icon(k)}</button>`).join('')}${!isUbuntu?`<div class="os-tray"><button data-osapp="settings" aria-label="Open network settings">${icon('network')}<span aria-hidden="true">${icon('volume')}</span></button><time>${clock.time}<br>${clock.date}</time></div>`:''}</nav><div id="osStartMenu" class="os-start-menu" hidden><label class="os-start-search">${icon('search')}<input id="osAppSearch" type="search" aria-label="Search installed apps" placeholder="${isUbuntu?'Type to search':'Search for apps'}"></label><h2>${isUbuntu?'Applications':'Pinned'}</h2><div class="os-pinned-apps">${Object.entries(apps).map(([k,t])=>`<button data-osapp="${k}" data-app-search="${esc((t+' '+appTitle(k)+(k==='tools'?' device manager hardware services disk management system information devmgmt.msc':'' )).toLowerCase())}" ${availableApps().includes(k)?'':`disabled title="Not included in ${esc(policy().name)}"`}>${icon(k)}<span>${k==='repos'?(isUbuntu?'Files':'File Explorer'):t}</span>${availableApps().includes(k)?'':'<small>Not in this lab</small>'}</button>`).join('')}</div><p id="osAppSearchEmpty" hidden>No matching apps in this desktop.</p><div class="os-recommended"><b>${isUbuntu?'Places':'Recommended'}</b><button data-osapp="repos">${icon('repos')}<span>Learning Repositories<small>Foundations and practice projects</small></span></button></div><footer><span class="os-user-avatar">S</span><span>Student</span><button id="osShutdown" aria-label="Shut down simulated computer" title="Shut down simulated computer">${icon('power')}</button></footer></div></div>${machine!==physical?'<div class="os-client-taskbar"><span>▦</span><b>'+esc(E.find(state(),physical)?.os==='Linux'?'Ubuntu client':'Windows 11 client')+'</b><span>VM console running on this display</span><button id="osDisconnectGuest">Disconnect console</button></div></div>':''}`;
 $('osGuestBack')?.addEventListener('click',leaveRemote);$('osDisconnectGuest')?.addEventListener('click',leaveRemote);
 const toggleStart=()=>{const menu=$('osStartMenu');menu.hidden=!menu.hidden;if(!menu.hidden)$('osAppSearch')?.focus();};$('osActivities')?.addEventListener('click',toggleStart);$('osStart').onclick=toggleStart;$('osTaskSearch')?.addEventListener('click',toggleStart);
 $('osAppSearch')?.addEventListener('input',e=>{let count=0;for(const b of dialog.querySelectorAll('[data-app-search]')){b.hidden=!b.dataset.appSearch.includes(e.target.value.toLowerCase());if(!b.hidden)count++;}$('osAppSearchEmpty').hidden=count>0;});
 $('osShutdown')?.addEventListener('click',()=>{if(ctx().vm){E.vmAction(state(),machine,'stop');leaveRemote();api.render?.();}else{ctx().device.on=false;close();}});
 $('osBootProfile')?.addEventListener('change',e=>{const d=E.find(state(),physical);if(!d||d.type!=='laptop')return;practice.endQuiet();remember();sessions.delete(physical);d.os=e.target.value;resetSession();api.render?.();draw();});$('osSave').onclick=()=>{const saved=api.save?.();$('osSave').textContent=saved?'Progress saved':'Save unavailable';};$('osPowerReturn')?.addEventListener('click',close);$('osGuideToggle').onclick=()=>{guide=!guide;draw()};
 $('osMinimize')?.addEventListener('click',()=>{minimized=true;draw()});$('osCloseApp')?.addEventListener('click',()=>{minimized=true;draw()});$('osMaximize')?.addEventListener('click',()=>{maximized=!maximized;windowPosition=null;draw()});
 for(const b of dialog.querySelectorAll('[data-osapp]'))b.onclick=()=>{if(b.dataset.networkSettings){settingsTab='network';networkEditing=false;}openApp(b.dataset.osapp);};
 bindApp();filterCommandCards();practice.bind(chrome);bindDrag();placeChrome();api.mountControls?.();drawLabTask();
 }
 const help=(title,text)=>guide?`<aside class="os-coach"><b>${title}</b><p>${text}</p></aside>`:'';
 const feedback=()=>notice?`<p class="os-notice" role="status">${esc(notice)}</p>`:'';
 function renderApp(){if(api.controlMarkup&&['lab','vms','cloud'].includes(app))return api.controlMarkup(app==='lab'?controlView:app,machine,controlTarget,controlSection);if(app==='terminal')return terminal();if(app==='settings')return settings();if(isBrowser(app))return browser();if(app==='vms')return vms();if(app==='cloud')return cloud();if(app==='tools')return admin.render();return `<div class="os-files-layout"><nav class="os-files-sidebar" aria-label="File locations"><b>${ubuntu()?'Places':'Quick access'}</b><button id="osFilesHome">${icon('home')} Home</button><button data-folder="foundations">${icon('repos')} Foundations</button><button data-folder="projects">${icon('repos')} Practice projects</button><span>${ubuntu()?'On this computer':'This PC'}<br>Learning Repositories</span></nav><div class="os-files-pane">${repos()}</div></div>`;}
 function terminal(){const bash=shell==='bash';return `${!bash?`<div class="os-terminal-tabs">${['powershell','cmd'].map(k=>`<button data-shell="${k}" aria-pressed="${shell===k}" title="Switch to ${k==='cmd'?'Command Prompt':'Windows PowerShell'}">${icon(k==='cmd'?'cmd':'powershell')} ${k==='cmd'?'Command Prompt':'Windows PowerShell'}</button>`).join('')}</div>`:''}<div class="os-terminal-layout"><div class="os-terminal os-shell-${shell}" aria-label="Terminal output">${!bash?`<pre class="os-shell-banner">${shell==='cmd'?'Microsoft Windows [Windows 11 teaching profile]':'Windows PowerShell'}
Copyright (C) Microsoft Corporation. All rights reserved.
</pre>`:''}${log.filter(r=>r.shell===shell).map(r=>`<div class="os-terminal-entry"><div class="os-command-line">${promptMarkup(r.prompt)}<span>${esc(r.command)}</span></div><pre class="${r.ok?'':'os-command-error'}">${esc(r.output)}</pre></div>`).join('')}<form id="osTerminalForm"><label for="osCommand">${promptMarkup()}</label><input id="osCommand" aria-label="Terminal command" autocomplete="off" autocapitalize="off" spellcheck="false" maxlength="600"><button class="os-sr-only" type="submit">Run command</button></form></div>${commandLibrary?library():''}</div>`;}
 function promptMarkup(prompt=shellName()){if(shell!=='bash')return `<span>${esc(prompt)} </span>`;const path=prompt.replace(/^student@ubuntu:/,'').replace(/\$$/,'');return `<span class="os-bash-user">student@ubuntu</span><span>:</span><span class="os-bash-path">${esc(path)}</span><span>$ </span>`;}
 function library(){const rows=commandCatalog(state(),shell,ctx());return `<aside class="os-command-library"><h3>Command library</h3><p>Choose a command. Read its job. Load it, then press Enter.</p><input id="osCommandSearch" type="search" aria-label="Find a practice command" placeholder="Find a command" value="${esc(commandFilter)}"><select id="osCommandCategory" aria-label="Command category">${['All',...new Set(rows.map(r=>r.category))].map(k=>`<option ${commandCategory===k?'selected':''}>${k}</option>`).join('')}</select><div>${rows.map((r,i)=>`<article data-command-card data-category="${r.category}" data-text="${esc((r.command+' '+r.why).toLowerCase())}"><code>${esc(r.command)}</code><p>${esc(r.why)}</p><button data-command-load="${i}">Load command</button></article>`).join('')}</div></aside>`;}
 function filterCommandCards(){for(const el of dialog.querySelectorAll('[data-command-card]'))el.hidden=!(commandCategory==='All'||el.dataset.category===commandCategory)||!el.dataset.text.includes(commandFilter.toLowerCase());}
 function settings(){const c=ctx(),n=address(state(),machine),raw=c.device?.network||{},val={...raw,...(n.ok?n:{})};return `<div class="os-settings-layout"><nav aria-label="Settings categories"><div class="os-settings-user"><span class="os-user-avatar">S</span><div><b>Student</b><small>Local account</small></div></div><button data-setting="network" class="${settingsTab==='network'?'selected':''}">${ubuntu()?'Network':'Network & internet'}</button><button data-setting="wifi" class="${settingsTab==='wifi'?'selected':''}" ${policy().wifi&&!c.vm?'':'disabled title="Available in the Wi-Fi lab"'}>Wi-Fi${policy().wifi?'':' · Locked'}</button><button data-setting="adapters" class="${settingsTab==='adapters'?'selected':''}">Advanced network settings</button><button data-setting="security" class="${settingsTab==='security'?'selected':''}">${ubuntu()?'Firewall rules':'Windows Security'}</button><button data-setting="about" class="${settingsTab==='about'?'selected':''}">System · About</button></nav><div class="os-settings-content"><p class="os-breadcrumb">Settings › ${settingsTab==='about'?'System › About':settingsTab==='security'?(ubuntu()?'Privacy › Firewall rules':'Privacy & security › Windows Security'):settingsTab==='adapters'?'Network & internet › Advanced network settings':settingsTab==='wifi'?'Network & internet › Wi-Fi':ubuntu()?'Network › Wired':'Network & internet › Ethernet'}</p><h2>${settingsTab==='about'?'About':settingsTab==='adapters'?'Advanced network settings':settingsTab==='security'?(ubuntu()?'Firewall rules':'Firewall & network protection'):settingsTab==='wifi'?'Wi-Fi':ubuntu()?'Network':'Network & internet'}</h2>${feedback()}${settingsTab==='adapters'?adapterSettings():settingsTab==='security'?securitySettings():settingsTab==='about'?`<form id="osRenameForm" class="os-rename-form">${field('osComputerName','Device name',configuration(state(),machine).hostname)}<button>Rename this PC</button></form><dl class="os-properties"><dt>Operating system profile</dt><dd>${ubuntu()?'Ubuntu 24.04 LTS':c.device?.os==='Hypervisor'?'Windows-style hypervisor management console':c.device?.os==='Windows Server'?'Windows Server desktop':'Windows 11 desktop'}</dd><dt>Machine</dt><dd>${esc(c.vm?.name||c.device.name)}</dd><dt>Role</dt><dd>${c.vm?'Virtual guest on '+esc(E.find(state(),c.vm.host)?.name):'Physical lab computer'}</dd><dt>Scope</dt><dd>This is a browser simulation. No real OS kernel, installation or device access.</dd></dl>`:settingsTab==='wifi'?wifiSettings():`<div class="os-connection-status"><b>${n.ok?(ubuntu()?'Wired — Connected':'Ethernet · Connected'):'Ethernet · Check connection'}</b><p>${n.ok?'Local network':esc(n.why)}</p></div><div class="os-ip-assignment"><div><b>${ubuntu()?'Wired connection 1':'IP assignment'}</b><span>${raw.mode==='dhcp'?'Automatic (DHCP)':'Manual'}</span></div><button id="osEditNetwork">${ubuntu()?'IPv4 settings':'Edit'}</button></div><form id="osNetworkForm" class="os-network-editor" ${networkEditing?'':'hidden'}><h3>${ubuntu()?'Wired · IPv4':'Edit IP settings'}</h3><label for="osIpMode">${ubuntu()?'IPv4 method':'Edit IP settings'}<select id="osIpMode"><option value="dhcp" ${raw.mode==='dhcp'?'selected':''}>Automatic (DHCP)</option><option value="static" ${raw.mode==='static'?'selected':''}>Manual</option></select></label><div id="osStaticFields" class="os-field-grid" ${raw.mode==='dhcp'?'hidden':''}>${field('osIp','IPv4 address',val.ip||'192.168.50.200')}${field('osMask','Subnet mask',val.mask||'255.255.255.0')}${field('osGateway','Default gateway',val.gateway||'192.168.50.1')}${field('osDns','Preferred DNS',val.dns||'192.168.50.1')}</div><button type="submit" class="os-primary">${ubuntu()?'Apply':'Save'}</button> <button id="osCancelNetwork" type="button">Cancel</button></form><dl class="os-properties"><dt>IPv4 address</dt><dd>${esc(n.ip||'Unavailable')}</dd><dt>Subnet mask</dt><dd>${esc(n.mask||'Unavailable')}</dd><dt>Gateway</dt><dd>${esc(n.gateway||'None')}</dd><dt>DNS</dt><dd>${esc(n.dns||'None')}</dd></dl><button data-osapp="terminal">Verify in Terminal →</button>`}</div></div>`;}
 function applyConfig(action,value){const r=configure(state(),ctx(),action,value);notice=r.message;if(r.ok)api.render?.();draw();}
 function adapterSettings(){const a=adapter(state(),ctx());return `<div class="os-adapter-card"><h3>Network adapters</h3><div><b>${esc(a.name)}</b><span>${esc(a.description)}</span><strong>${esc(a.status)}</strong><button id="osAdapterToggle">${a.adapterEnabled?'Disable':'Enable'}</button></div><p>Disabling the adapter disconnects it. Its saved address stays in place.</p><button id="osOpenDeviceManager">${ubuntu()?'Inspect hardware':'Open Device Manager'}</button><button data-osapp="terminal">Verify in Terminal</button></div>`;}
 function securitySettings(){const q=configuration(state(),machine);return `<div class="os-security-panel"><h3>${ubuntu()?'Lab inbound rules':'Microsoft Defender Firewall · lab rules'}</h3><p>The firewall remains on in this model. Allow or block the preinstalled web and file services below.</p><label class="os-inbound-toggle"><input id="osAllowInbound" type="checkbox" ${q.allowServices?'checked':''}>Allow inbound LabHTTPS (TCP 443) and LabSMB (TCP 445)</label><p>These rules affect incoming requests to this computer. They do not start a service or fix its network. ICMP is separate in this exercise.</p></div>`;}
 function wifiSettings(){if(!policy().wifi)return '<p>Wi-Fi controls are enabled in the Wi-Fi network lab and Free build. This exercise uses Ethernet.</p>';const c=ctx();if(c.vm||c.device.type!=='laptop')return '<p>This machine has a wired virtual or server adapter. Practice Wi-Fi on the physical laptop; a VM does not automatically inherit the host’s radio controls.</p>';const aps=E.ofType(state(),'ap').filter(a=>E.powered(state(),a.id));return `${help('Join first. Get an address second.','Build and power the access point and its switch uplink. Select its SSID below. Use a teaching passphrase, not a personal password.')}<p>Active connection: ${c.device.network.wifi?esc(c.device.network.ssid||'No SSID'):'Ethernet'}</p><form id="osWifiForm"><label for="osSsid">Available networks<select id="osSsid">${aps.map(a=>`<option value="${esc(a.ssid)}" ${a.ssid===c.device.network.ssid?'selected':''}>${esc(a.ssid)} · ${a.band} GHz · ${esc(a.security)}</option>`).join('')}</select></label>${!aps.length?'<p>No powered access point found. Return to the lab and connect its power/uplink.</p>':''}${field('osWifiPassword','Network security key / password','','password')}<button class="os-primary" ${aps.length?'':'disabled'}>Connect</button><button type="button" id="osEthernet">Use Ethernet instead</button></form><p>${esc(E.wifiAssociation(state(),machine).why)}</p>`;}
 function localPage(url){return api.localPage?.(machine,url)||null;}
 function browser(){const b=browserStates[app],local=localPage(b.url);if(b.result?.management||local)b.result=local||{ok:false,why:'The router address has changed. Reopen Device setup in Lab console and choose the router again.'};const content=b.result?.management&&b.result.ok?api.controlMarkup?.('router',machine,b.result.device,'Router configuration',b.url)||'':'';return browserMarkup(app,b,icon,content);}
 function browserEvidence(r){if(r?.ok&&!r.management){progress().page=true;practice.mark('browser:success');}if(r&&!r.management&&!r.unsupported)api.networkResult?.({source:machine,target:'internet',protocol:'https'},r);draw();}
 function browse(url,replace=false){browserEvidence(visitBrowser(browserStates[app],url,()=>request(state(),machine),replace,localPage));}
 function repos(){const p=progress();if(lessonId){const l=lessons.find(x=>x.id===lessonId);return `<div class="os-repo-toolbar"><button id="osRepoBack">← Foundations</button><span>Learning-Repositories / 01-Foundations</span></div><article class="os-lesson"><p class="os-eyebrow">${esc(l.level)} · ${allowedLessons().indexOf(l)+1} / ${allowedLessons().length}</p><h2>${esc(l.title)}</h2><p class="os-lede">${esc(l.summary)}</p><ol class="os-workflow">${l.path.map((x,i)=>`<li><b>${i+1}</b><span>${esc(x)}</span></li>`).join('')}</ol>${l.sections.map(([h,t])=>`<section><h3>${esc(h)}</h3><p>${esc(t)}</p></section>`).join('')}${l.id==='subnet'?subnetTool():''}<div class="os-try"><b>Try it in this computer’s Terminal</b><code>${esc(l.commands[ubuntu()?'ubuntu':'windows'])}</code><button id="osTryCommand">Load command into Terminal</button><small>Loading does not run the command. Press Enter when you are ready.</small></div><fieldset class="os-quiz"><legend>Check your understanding: ${esc(l.quiz[0])}</legend>${l.quiz[1].map((a,i)=>`<button data-quiz="${i}">${esc(a)}</button>`).join('')}<p role="status">${esc(quizFeedback|| (p.quizzes.includes(l.id)?'✓ Answered correctly on this build.':''))}</p></fieldset><p class="os-sources">Read more: ${l.refs.map(k=>`<a href="${references[k][1]}" target="_blank" rel="noopener">${esc(references[k][0])}</a>`).join(' · ')}</p><div class="os-lesson-nav">${allowedLessons().indexOf(l)>0?'<button id="osPreviousLesson">← Previous lesson</button>':''}${allowedLessons().indexOf(l)<allowedLessons().length-1?'<button id="osNextLesson" class="os-primary">Next lesson →</button>':''}</div><p class="os-small">Original lessons aligned with A+ networking, operating systems and virtualization topics. Subnet arithmetic and VLAN exercises include extension practice. These are not official CompTIA exam questions.</p></article>`;}
 if(projectId){const project=projects.find(x=>x.id===projectId);return `<div class="os-repo-toolbar"><button id="osProjectBack">← Practice projects</button><span>02-Practice-Projects</span></div><article class="os-lesson"><p class="os-eyebrow">DO → OBSERVE → VERIFY</p><h2>${esc(project.title)}</h2><p class="os-lede">${esc(project.task)}</p>${feedback()}<button id="osProjectApp" class="os-primary">Open ${apps[project.app]}</button><button id="osCheckProject">Check this project</button><button data-lesson="${project.lesson}">Explain the concept</button><p>${p.projects.includes(project.id)?'✓ Completed on this build. You can repeat it.':'Come back to this project and check after doing the task.'}</p><p class="os-small">Project checks use current lab state and successful commands, not a timer. Follow the guided build first if its required equipment is missing.</p></article>`;}
 return `<div class="os-repo-toolbar"><button id="osRepoHome">⌂ Home</button><span>Learning-Repositories ${folder==='home'?'':' / '+(folder==='foundations'?'01-Foundations':'02-Practice-Projects')}</span><label class="os-search">Find a lesson<input id="osRepoSearch" type="search" placeholder="IP, mask, Wi-Fi, cloud…"></label></div><div class="os-repo-content"><p class="os-eyebrow">Learning Repositories</p><h2>${folder==='home'?'Home':folder==='foundations'?'01 · Foundations':'02 · Practice projects'}</h2>${folder==='home'?`${help('New here? Start with Foundations','Read lesson 01, follow the numbered workflow, and try the command. After the first few lessons, open Practice projects. Only this lab’s lessons and projects appear here. Everything stays on this computer’s screen.')}<div class="os-folders"><button data-folder="foundations">${icon('repos')}<b>01 · Foundations</b><span>${allowedLessons().length} lessons for this lab · definitions · workflow maps · questions</span></button><button data-folder="projects">${icon('terminal')}<b>02 · Practice projects</b><span>${allowedProjects().length} practice tasks · live checks · repeat anytime</span></button></div><p>Progress: ${allowedLessons().filter(l=>p.quizzes.includes(l.id)).length} / ${allowedLessons().length} knowledge checks · ${allowedProjects().filter(l=>p.projects.includes(l.id)).length} / ${allowedProjects().length} projects. Use Save my progress in the lab to keep this with your build.</p><p class="os-small">These are virtual learning folders packaged with the simulator. No Git account, download or external terminal is required.</p>`:`<div id="osRepoItems" class="os-repo-grid">${folder==='foundations'?allowedLessons().map(l=>`<button data-lesson="${l.id}" data-search="${esc([l.title,l.summary,...l.sections.flat()].join(' ').toLowerCase())}"><span class="os-file-icon">${p.quizzes.includes(l.id)?'✓':'≡'}</span><b>${esc(l.title)}</b><span>${esc(l.summary)}</span><small>${esc(l.level)}</small></button>`).join(''):allowedProjects().map(pj=>`<button data-project="${pj.id}" data-search="${esc((pj.title+' '+pj.task).toLowerCase())}"><span class="os-file-icon">${p.projects.includes(pj.id)?'✓':'▸'}</span><b>${esc(pj.title)}</b><span>${esc(pj.task)}</span></button>`).join('')}</div><p id="osSearchEmpty" hidden>No matching lessons. Try a shorter word.</p>`}</div>`;}
 function subnetTool(){return `<section class="os-subnet"><h3>Subnet workbench</h3><p>Move the network/host boundary. Watch the address range change.</p><form id="osSubnetForm" class="os-field-grid">${field('osSubnetIp','IPv4 address','192.168.50.100')}<label>Network bits / prefix<input id="osPrefix" type="number" min="0" max="32" value="24"></label><button class="os-primary">Calculate</button></form><div id="osSubnetResult" aria-live="polite"></div></section>`;}
 function vms(){if(!availableApps().includes('vms'))return '<p>Virtual machines are locked in this lab.</p>';const hosts=E.ofType(state(),'server');return `<div class="os-manager"><h2>Virtual Machine Manager</h2><p>Management runs on this client. The server supplies each guest’s CPU, RAM and disk. This lab checks LAN reachability; real remote consoles also require authentication, permissions and their management ports.</p>${hosts.map(h=>`<button data-host-open="${h.id}" ${E.test(state(),physical,h.id,'ping').ok?'':'disabled'}>Open host console · ${esc(h.name)}</button>`).join('')}${help('A VM needs a prepared host','Build the server in the guided lab first. Create the guest, install its Linux OS, start it, then Open Ubuntu desktop. Its console stays inside this client’s screen. External reaches the LAN. Private and Internal have no Internet route here.')}${feedback()}<form id="osCreateVm" class="os-field-grid"><label>Host<select id="osVmHost">${hosts.filter(h=>E.test(state(),physical,h.id,'ping').ok).map(h=>`<option value="${h.id}">${esc(h.name)}</option>`).join('')}</select></label>${field('osVmName','Guest name','Ubuntu-Lab')}${field('osVmRam','RAM · GB',4,'number')}${field('osVmCpu','vCPUs',2,'number')}${field('osVmDisk','Disk · GB',40,'number')}<button class="os-primary" ${hosts.length?'':'disabled'}>Create Ubuntu VM definition</button></form>${state().vms.map(v=>{const r=screenSession(state(),v.id,physical);return `<article class="os-vm-row"><h3>${esc(v.name)}</h3><p>${esc(r.ok?E.vmStatus(state(),v).why:r.why)}</p><p>${v.cpu} vCPUs · ${v.ram} GB RAM · ${v.disk} GB disk</p><div class="os-vm-buttons"><button data-guest-install="${v.id}" ${v.os?'disabled':''}>${v.os?'OS installed':'Install Ubuntu guest OS'}</button><button data-guest-run="${v.id}" ${v.os?'':'disabled'}>${v.running?'Stop VM':'Start VM'}</button><button data-guest-open="${v.id}" ${r.ok?'':'disabled'}>Open Ubuntu desktop</button><label>Virtual switch<select data-guest-switch="${v.id}">${['external','internal','private'].map(k=>`<option ${v.mode===k?'selected':''}>${k}</option>`).join('')}</select></label></div></article>`}).join('')||'<p>No guests yet. Your host must be powered, have its parts, healthy storage, a hypervisor and firmware virtualization enabled.</p>'}</div>`;}
 function cloud(){if(!policy().cloud)return '<p>Cloud tools are locked in this lab.</p>';const s=state(),cl=s.cloud;return `<div class="os-manager"><h2>Cloud learning console</h2>${help('Choose what you manage','IaaS: manage the OS and app. PaaS: manage your code and data. SaaS: use the provider’s app. This console only creates a teaching record, never a real account or bill.')}${feedback()}<form id="osCloudForm" class="os-field-grid"><label>Deployment<select id="osCloudModel">${['public','private','hybrid','community'].map(k=>`<option ${cl.model===k?'selected':''}>${k}</option>`).join('')}</select></label><label>Service model<select id="osCloudService">${['iaas','paas','saas'].map(k=>`<option value="${k}" ${cl.service===k?'selected':''}>${k.toUpperCase()}</option>`).join('')}</select></label><button class="os-primary">Provision learning account</button></form><h3>Separate recovery copy</h3><label>Source server / NAS<select id="osBackupSource">${s.devices.filter(d=>['server','nas'].includes(d.type)).map(d=>`<option value="${d.id}">${esc(d.name)}</option>`).join('')}</select></label><button id="osBackup">Run simulated off-site backup</button><button id="osVerifyBackup" ${cl.backup?'':'disabled'}>Verify recovery record</button><p>${cl.backup?'Recovery copy: '+esc(cl.sourceName)+(cl.verified?' · verified':' · verification needed'):'No recovery copy yet.'}</p><button data-lesson="cloud">Explain cloud models →</button></div>`;}
 function recordCommand(command,r){if(!r.ok)return;const p=progress();if(/^(Get-NetIPConfiguration|ipconfig(?: \/all)?|ip addr|ip address|nmcli device show)$/i.test(command))p.commands.push('read');if(/^(Resolve-DnsName|nslookup|resolvectl query) example\.com$/i.test(command))p.commands.push('dns');if(command==='ss -lnt')p.commands.push('ports');p.commands=[...new Set(p.commands)];}
 function checkProject(p){const c=ctx(),n=address(state(),machine),prog=progress();const checks={read:()=>prog.commands.includes('read'),static:()=>n.ok&&c.device.network.mode==='static',dns:()=>prog.commands.includes('dns'),page:()=>prog.page===true&&request(state(),machine).ok,automatic:()=>n.ok&&c.device.network.mode==='dhcp',wifi:()=>!c.vm&&c.device.network.wifi&&request(state(),machine).ok,service:()=>!!c.vm&&c.vm.service&&prog.commands.includes('ports')&&state().devices.some(d=>d.type==='laptop'&&E.testVM(state(),d.id,machine).ok),cloud:()=>state().cloud.backup&&state().cloud.verified};const passed=!!checks[p.check]?.();if(passed&&!prog.projects.includes(p.id))prog.projects.push(p.id);return passed;}
 function bindApp(){if(app==='tools')admin.bind(dialog);$('osCommandSearch')?.addEventListener('input',e=>{commandFilter=e.target.value;filterCommandCards();});$('osCommandCategory')?.addEventListener('change',e=>{commandCategory=e.target.value;filterCommandCards();});for(const b of dialog.querySelectorAll('[data-command-load]'))b.onclick=()=>{const r=commandCatalog(state(),shell,ctx())[Number(b.dataset.commandLoad)];commandLibrary=false;draw();$('osCommand').value=r.command;$('osCommand').focus();};$('osFilesHome')?.addEventListener('click',()=>{folder='home';lessonId=projectId=null;draw()});$('osEditNetwork')?.addEventListener('click',()=>{networkEditing=true;draw();$('osIpMode')?.focus()});$('osCancelNetwork')?.addEventListener('click',()=>{networkEditing=false;draw()});for(const b of dialog.querySelectorAll('[data-shell]'))b.onclick=()=>{chooseShell(b.dataset.shell);draw();$('osCommand').focus()};$('osCommandHelp')?.addEventListener('click',()=>{commandLibrary=!commandLibrary;commandFilter='';commandCategory='All';draw()});
 $('osTerminalForm')?.addEventListener('submit',e=>{e.preventDefault();execute($('osCommand').value)});$('osCommand')?.addEventListener('keydown',e=>{if(e.ctrlKey&&e.key.toLowerCase()==='l'){e.preventDefault();execute('clear');return;}if(e.ctrlKey&&e.key.toLowerCase()==='c'){e.preventDefault();e.target.value='';return;}if(['ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();historyIndex=Math.max(0,Math.min(history.length,historyIndex+(e.key==='ArrowUp'?-1:1)));e.target.value=history[historyIndex]||'';}});
 for(const b of dialog.querySelectorAll('[data-setting]'))b.onclick=()=>{settingsTab=b.dataset.setting;practice.mark('settings:'+settingsTab);notice='';draw()};$('osIpMode')?.addEventListener('change',e=>{$('osStaticFields').hidden=e.target.value==='dhcp'});
 $('osAdapterToggle')?.addEventListener('click',()=>applyConfig('adapter',!configuration(state(),machine).adapterEnabled));$('osOpenDeviceManager')?.addEventListener('click',()=>{admin.select('devices');openApp('tools')});$('osAllowInbound')?.addEventListener('change',e=>applyConfig('inbound',e.target.checked));$('osRenameForm')?.addEventListener('submit',e=>{e.preventDefault();applyConfig('hostname',$('osComputerName').value.trim())});
 $('osNetworkForm')?.addEventListener('submit',e=>{e.preventDefault();const mode=$('osIpMode').value,r=changeAddress(state(),machine,mode==='dhcp'?{mode}:{mode,ip:$('osIp').value.trim(),mask:$('osMask').value.trim(),gateway:$('osGateway').value.trim(),dns:$('osDns').value.trim()});notice=r.message;if(r.ok){networkEditing=false;api.render?.();}draw()});
 $('osWifiForm')?.addEventListener('submit',e=>{e.preventDefault();const d=ctx().device,r=changeAddress(state(),machine,{mode:d.network.mode,wifi:true,ssid:$('osSsid').value,password:$('osWifiPassword').value});const a=E.wifiAssociation(state(),machine);notice=a.ok?'Joined. '+address(state(),machine).why:a.why;api.render?.();draw()});$('osEthernet')?.addEventListener('click',()=>{const r=changeAddress(state(),machine,{mode:ctx().device.network.mode,wifi:false});notice=r.message;api.render?.();draw()});
 $('osBrowserForm')?.addEventListener('submit',e=>{e.preventDefault();browse($('osUrl').value)});$('osBrowserExample')?.addEventListener('click',()=>browse('https://example.com'));$('osBrowserHome')?.addEventListener('click',()=>browse('about:newtab'));$('osBrowserReload')?.addEventListener('click',()=>browse(browserStates[app].url,true));$('osBrowserBack')?.addEventListener('click',()=>browserEvidence(moveBrowser(browserStates[app],-1,()=>request(state(),machine),localPage)));$('osBrowserForward')?.addEventListener('click',()=>browserEvidence(moveBrowser(browserStates[app],1,()=>request(state(),machine),localPage)));
 for(const b of dialog.querySelectorAll('[data-folder]'))b.onclick=()=>{folder=b.dataset.folder;lessonId=projectId=null;draw()};for(const b of dialog.querySelectorAll('[data-lesson]'))b.onclick=()=>{app='repos';folder='foundations';lessonId=b.dataset.lesson;projectId=null;quizFeedback='';draw()};for(const b of dialog.querySelectorAll('[data-project]'))b.onclick=()=>{projectId=b.dataset.project;lessonId=null;notice='';draw()};
 $('osRepoHome')?.addEventListener('click',()=>{folder='home';lessonId=projectId=null;draw()});$('osRepoBack')?.addEventListener('click',()=>{lessonId=null;folder='foundations';draw()});$('osProjectBack')?.addEventListener('click',()=>{projectId=null;folder='projects';draw()});
 $('osRepoSearch')?.addEventListener('input',e=>{if(folder==='home'){folder='foundations';const q=e.target.value;draw();$('osRepoSearch').value=q;$('osRepoSearch').focus();$('osRepoSearch').dispatchEvent(new Event('input'));return;}let count=0;for(const b of dialog.querySelectorAll('[data-search]')){b.hidden=!b.dataset.search.includes(e.target.value.toLowerCase());if(!b.hidden)count++;}$('osSearchEmpty').hidden=count>0;});
 const current=()=>lessons.find(l=>l.id===lessonId);for(const b of dialog.querySelectorAll('[data-quiz]'))b.onclick=()=>{const l=current(),right=Number(b.dataset.quiz)===l.quiz[2];quizFeedback=right?l.quiz[3]:'Try again. Read the explanation above and compare each choice.';if(right&&!progress().quizzes.includes(l.id))progress().quizzes.push(l.id);const scroll=dialog.querySelector('.os-app-body').scrollTop;draw();dialog.querySelector('.os-app-body').scrollTop=scroll;};
 $('osPreviousLesson')?.addEventListener('click',()=>{lessonId=allowedLessons()[allowedLessons().indexOf(current())-1].id;quizFeedback='';draw()});$('osNextLesson')?.addEventListener('click',()=>{lessonId=allowedLessons()[allowedLessons().indexOf(current())+1].id;quizFeedback='';draw()});$('osTryCommand')?.addEventListener('click',()=>{const command=current().commands[ubuntu()?'ubuntu':'windows'];if(!ubuntu())chooseShell(/^(ipconfig|netstat|tracert|nslookup)/i.test(command)?'cmd':'powershell');openApp('terminal');$('osCommand').value=command;});
 $('osSubnetForm')?.addEventListener('submit',e=>{e.preventDefault();calculateSubnet()});if($('osSubnetResult'))calculateSubnet();
 $('osProjectApp')?.addEventListener('click',()=>{const p=projects.find(x=>x.id===projectId);openApp(p.id==='cloud'?'cloud':p.app)});$('osCheckProject')?.addEventListener('click',()=>{const p=projects.find(x=>x.id===projectId);notice=checkProject(p)?'✓ Project passed. The lab detected the required evidence.':'Not complete yet. Follow the task, check power and network settings, then try again.';draw()});
 $('osCreateVm')?.addEventListener('submit',e=>{e.preventDefault();if(!policy().vm||!E.test(state(),physical,$('osVmHost').value,'ping').ok){notice='Connect this client to a prepared hypervisor host first.';draw();return;}const r=E.createVM(state(),$('osVmHost').value,$('osVmName').value,Number($('osVmRam').value),Number($('osVmCpu').value),Number($('osVmDisk').value),'external');notice=r.message;api.render?.();draw()});
 for(const b of dialog.querySelectorAll('[data-host-open]'))b.onclick=()=>open(b.dataset.hostOpen);for(const b of dialog.querySelectorAll('[data-guest-install]'))b.onclick=()=>guestAction(b.dataset.guestInstall,'install');for(const b of dialog.querySelectorAll('[data-guest-run]'))b.onclick=()=>{const v=state().vms.find(v=>v.id===b.dataset.guestRun);guestAction(v.id,v.running?'stop':'start')};for(const b of dialog.querySelectorAll('[data-guest-open]'))b.onclick=()=>open(b.dataset.guestOpen);for(const b of dialog.querySelectorAll('[data-guest-switch]'))b.onchange=()=>{const v=state().vms.find(v=>v.id===b.dataset.guestSwitch);if(!policy().vm||!E.test(state(),physical,v.host,'ping').ok){notice='Restore the management path to the host first.';draw();return;}v.mode=b.value;api.render?.();draw()};
 $('osCloudForm')?.addEventListener('submit',e=>{e.preventDefault();Object.assign(state().cloud,{model:$('osCloudModel').value,service:$('osCloudService').value,account:true});notice='Learning account provisioned. No real subscription was created.';api.render?.();draw()});$('osBackup')?.addEventListener('click',()=>{const source=E.find(state(),$('osBackupSource').value);if(!source){notice='Prepare a server or NAS first.';draw();return;}const r=E.test(state(),source.id,'cloud','https');if(r.ok)Object.assign(state().cloud,{backup:true,verified:false,sourceName:source.name,sourceId:source.id,capacity:E.raidStatus(source).usable});notice=r.ok?'Simulated recovery record saved. Verify it next.':r.why;api.render?.();draw()});$('osVerifyBackup')?.addEventListener('click',()=>{if(state().cloud.backup)state().cloud.verified=true;notice='Recovery record verified. A real backup plan also tests file restoration.';api.render?.();draw()});
 }
 function execute(raw){const command=raw.trim(),oldPrompt=shellName(),r=runCommand(state(),machine,command,shell,{cwd});if(r.cwd!==undefined)cwd=r.cwd;if(r.clear)log=log.filter(r=>r.shell!==shell);else{log.push({shell,prompt:oldPrompt,command,output:r.output,ok:r.ok});log=log.slice(-60);}if(command){history.push(command);history=history.slice(-60);}historyIndex=history.length;recordCommand(command,r);if(r.ok){if(/^(ipconfig(?: \/all)?|Get-NetIPConfiguration|ip addr)$/.test(command))practice.mark('command:read');if(/^ping /i.test(command))practice.mark('command:ping');if(/^(nslookup|Resolve-DnsName|resolvectl query) /i.test(command))practice.mark('command:dns');if(/^(netstat -ano|ss -lnt|Get-NetTCPConnection)/i.test(command))practice.mark('command:ports');}if(r.launch){if(r.launch.tool)admin.select(r.launch.tool);if(r.launch.tab)settingsTab=r.launch.tab;openApp(r.launch.app);return;}if(r.changed)api.render?.();draw();$('osCommand')?.focus();const term=dialog.querySelector('.os-terminal');if(term)term.scrollTop=term.scrollHeight;}
 function guestAction(id,action){if(!policy().vm)return;const v=state().vms.find(v=>v.id===id);if(!v||!E.test(state(),physical,v.host,'ping').ok){notice='Restore the client’s network path to the VM host first.';draw();return;}const r=E.vmAction(state(),id,action);notice=r.message;api.render?.();draw();}
 function calculateSubnet(){const r=subnet($('osSubnetIp').value.trim(),$('osPrefix').value);$('osSubnetResult').innerHTML=r?`<div class="os-bits" aria-label="${r.prefix} network bits followed by ${32-r.prefix} host bits">${Array.from({length:32},(_,i)=>`<span class="${i<r.prefix?'net':'host'}">${i<r.prefix?'1':'0'}</span>`).join('')}</div><p><b>Blue = network bits. Amber = host bits.</b></p><dl class="os-properties"><dt>Mask</dt><dd>${r.mask}</dd><dt>Network</dt><dd>${r.network}/${r.prefix}</dd><dt>Broadcast</dt><dd>${r.broadcast}</dd><dt>Host range</dt><dd>${r.first} → ${r.last}</dd><dt>Address count</dt><dd>${r.addresses.toLocaleString()} total · ${r.hosts.toLocaleString()} host addresses</dd></dl><p>${esc(r.note)}</p>`:'<p>Use a valid four-octet IPv4 address and a prefix from 0 to 32.</p>';}
 function bindDrag(){const bar=dialog.querySelector('.os-titlebar'),win=dialog.querySelector('.os-window');if(!bar||maximized)return;bar.onpointerdown=e=>{if(e.target.closest('button')||e.button!==0)return;const start={x:e.clientX,y:e.clientY,dx:windowPosition?.x||0,dy:windowPosition?.y||0},area=dialog.querySelector('.os-workspace').getBoundingClientRect(),rect=win.getBoundingClientRect();bar.setPointerCapture(e.pointerId);bar.onpointermove=ev=>{const scale=area.width/dialog.querySelector('.os-workspace').clientWidth;const dx=Math.max(area.left+8-rect.left,Math.min(area.right-8-rect.right,ev.clientX-start.x)),dy=Math.max(area.top+36-rect.top,Math.min(area.bottom-70-rect.bottom,ev.clientY-start.y));windowPosition={x:start.dx+dx/scale,y:start.dy+dy/scale};win.style.setProperty('--os-dx',windowPosition.x+'px');win.style.setProperty('--os-dy',windowPosition.y+'px');};bar.onpointerup=bar.onpointercancel=()=>{bar.onpointermove=null;};};}
 dialog.addEventListener('pointerdown',e=>{e.stopPropagation();const menu=$('osStartMenu');if(menu&&!menu.hidden&&!e.target.closest('#osStartMenu,#osStart,#osTaskSearch,#osActivities'))menu.hidden=true;});dialog.addEventListener('keydown',e=>{if(e.key==='Escape'&&app==='tools'&&admin.escape()){e.preventDefault();e.stopPropagation();return;}if(e.key==='Escape'&&$('osStartMenu')&&!$('osStartMenu').hidden){e.preventDefault();e.stopPropagation();$('osStartMenu').hidden=true;$('osStart').focus();}});dialog.addEventListener('dblclick',e=>e.stopPropagation());
 function clientFor(id){const target=E.find(state(),id);return target?.type==='laptop'?target.id:E.ofType(state(),'laptop').find(d=>E.ready(state(),d.id).ok)?.id;}
 function openLab(view='home'){const id=clientFor(physical);if(!id){api.result({ok:false,message:'Add a laptop, connect its power and switch it on. Configuration opens on that laptop.'});return false;}if(['vms','cloud'].includes(view)&&!screenPolicy(state())[view==='vms'?'vm':'cloud']){api.result({ok:false,message:'That workspace is not part of this lab.'});return false;}if(!dialog.open||machine!==id){if(!open(id))return false;}controlView=view;app=['vms','cloud'].includes(view)?view:'lab';minimized=false;draw();return true;}
 function configureDevice(id,group=null,field=null,choose=null){const d=E.find(state(),id),client=clientFor(d?.type==='laptop'?id:physical);if(!d||!client){api.result({ok:false,message:'Power a laptop first. You will configure this equipment from its screen.'});return false;}if(!dialog.open||machine!==client){if(!open(client))return false;}controlTarget=id;controlSection=group;controlField=field;controlChoice=choose;api.selectControl?.(id,group,field,choose);
 if(d.type==='laptop'){app='settings';settingsTab=field==='useWifi'?'wifi':'network';networkEditing=field!=='useWifi';minimized=false;draw();return true;}
 if(d.type==='router'){app='browser';minimized=false;visitBrowser(browserStates.browser,'http://'+d.router.lan,()=>request(state(),machine),false,localPage);draw();return true;}
 app='lab';controlView='device';minimized=false;draw();const el=document.getElementById(field);if(el&&choose)el.value=choose;el?.focus();return true;}
 function runNetworkTest(spec){const id=clientFor(E.find(state(),spec.source)?.type==='laptop'?spec.source:physical);if(!id){api.result({ok:false,message:'Power a laptop before running network tests.'});return false;}if(!dialog.open||machine!==id){if(!open(id))return false;}
 if(spec.protocol==='https'&&spec.target==='internet'&&spec.source===id){app='browser';minimized=false;visitBrowser(browserStates.browser,'https://example.com',()=>request(state(),machine));const r=browserStates.browser.result;api.networkResult?.(spec,r);if(r.ok){progress().page=true;practice.mark('browser:success');}draw();return true;}
 openLab('tests');const guest=state().vms.some(v=>v.id===spec.target),r=guest||spec.vm?(spec.protocol==='https'?E.testVM(state(),spec.source,spec.target):{ok:false,why:'This VM diagnostic checks HTTPS only. Choose HTTPS (TCP 443), or use the simulated Terminal to ping the guest address.',trace:[]}):E.test(state(),spec.source,spec.target,spec.protocol);api.networkResult?.(spec,r);draw();return true;}
 function drawLabTask(){const old=chrome.querySelector('#osBuildTask');old?.remove();const g=api.guideInfo?.(),challenge=api.challengeInfo?.();if(!g&&challenge){const el=document.createElement('div');el.id='osBuildTask';el.className='os-build-task';el.innerHTML='<div><b>Independent challenge · '+esc(challenge.title)+'</b><p>'+esc(challenge.goal)+'</p>'+challenge.result+'</div><button id="osCheckChallenge">Check my result</button>';chrome.prepend(el);el.querySelector('button').onclick=()=>{api.checkChallenge?.();drawLabTask();};return;}if(!g)return;const el=document.createElement('div');el.id='osBuildTask';el.className='os-build-task';el.innerHTML=`<div><b>Lab task ${g.index+1} · ${esc(g.title)}</b><p>${esc(g.instruction)}</p>${g.coach?coachMarkup(g.coach,esc,g.pass):''}${g.issues?.length?`<div class="os-setup-feedback" role="status"><b>Check these settings</b><ul>${g.issues.map(text=>`<li>${esc(text)}</li>`).join('')}</ul></div>`:''}</div><button id="osBuildContinue" ${g.pass?'':'disabled'}>${g.pass?'Continue lab →':'Complete this task'}</button>`;chrome.prepend(el);el.querySelector('button').onclick=()=>{api.guideNext?.();const next=api.guideInfo?.();if(next?.screen)api.guideAction?.();else close();drawLabTask();};}
 function refresh(){if(!dialog.open)return;if(owner!==state()){close();sessions.clear();physical=null;owner=state();return;}if(availability!==JSON.stringify(screenSession(state(),machine,physical)))draw();else {api.refreshControls?.();drawLabTask();}}
 return {open,close,refresh,openLab,configureDevice,runNetworkTest,redraw:draw};
}
